import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root object
  const root = new Group();

  // Geometry (tessellated plane)
  const geometry = new PlaneGeometry(1, 1, 64, 64);
  const material = new MeshStandardNodeMaterial();
  material.transparent = true;

  // Load textures asynchronously, material updates later
  const imagePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  imagePromise.then((tex) => {
    material.mapNode = texture(tex);
    material.needsUpdate = true;
  });

  depthPromise.then((tex) => {
    const intensity =
      (config.cinematicPrimitives?.find((p) => p.name === 'parallax-scroll')
        ?.params?.intensity ?? 0.25) * 1.0;
    material.displacementNode = texture(tex).mul(float(intensity));
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply cinematic primitives
  const primitiveRefs = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const ref = fn(root, prim.params);
        primitiveRefs.push(ref);
      }
    }
  }

  // Event handlers storage
  const handlers = {};

  // Hover lift (rise‑in)
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(root.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });
  handlers.hover = () => hoverTl.play(0);
  handlers.hoverOut = () => hoverTl.reverse();

  // Click press‑down + emit
  handlers.click = () => {
    const pressTl = gsap.timeline();
    pressTl.to(
      root.scale,
      { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' }
    );
    pressTl.to(
      root.scale,
      { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power4.out' }
    );
    ctx.emit('hub-features.select', {});
  };

  // Store timelines for cleanup
  const timelines = [hoverTl];

  // Attach handlers and cleanup to userData
  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imagePromise.then((tex) => tex.dispose());
    depthPromise.then((tex) => tex.dispose());
    primitiveRefs.forEach((ref) => ref.cleanup && ref.cleanup());
    timelines.forEach((tl) => tl.kill());
  };

  return root;
}
